import zipfile
import re
import xml.etree.ElementTree as ET

NS = {
    "m": "http://schemas.openxmlformats.org/spreadsheetml/2006/main",
    "r": "http://schemas.openxmlformats.org/officeDocument/2006/relationships",
}

def col_to_idx(ref):
    m = re.match(r"([A-Z]+)", ref)
    letters = m.group(1)
    idx = 0
    for ch in letters:
        idx = idx * 26 + (ord(ch) - ord("A") + 1)
    return idx

def read_shared_strings(z):
    shared = []
    if "xl/sharedStrings.xml" in z.namelist():
        root = ET.fromstring(z.read("xl/sharedStrings.xml"))
        for si in root.findall("m:si", NS):
            texts = [t.text or "" for t in si.iter("{http://schemas.openxmlformats.org/spreadsheetml/2006/main}t")]
            shared.append("".join(texts))
    return shared

def sheet_map(z):
    wb = ET.fromstring(z.read("xl/workbook.xml"))
    rels = ET.fromstring(z.read("xl/_rels/workbook.xml.rels"))
    rel_target = {}
    for rel in rels.findall("m:Relationship", NS):
        rel_target[rel.get("Id")] = rel.get("Target")
    sheets = []
    for sh in wb.find("m:sheets", NS).findall("m:sheet", NS):
        rid = sh.get("{http://schemas.openxmlformats.org/officeDocument/2006/relationships}id")
        target = rel_target[rid]
        if not target.startswith("xl/"):
            target = "xl/" + target
        sheets.append((sh.get("name"), target))
    return sheets

def read_sheet(z, path, shared):
    root = ET.fromstring(z.read(path))
    rows = []
    for row in root.iter("{http://schemas.openxmlformats.org/spreadsheetml/2006/main}row"):
        cells = {}
        for c in row.findall("m:c", NS):
            ref = c.get("r")
            t = c.get("t")
            v = c.find("m:v", NS)
            val = None
            if t == "inlineStr":
                is_el = c.find("m:is", NS)
                if is_el is not None:
                    val = "".join(x.text or "" for x in is_el.iter("{http://schemas.openxmlformats.org/spreadsheetml/2006/main}t"))
            elif v is not None:
                raw = v.text or ""
                if t == "s":
                    val = shared[int(raw)]
                elif t == "b":
                    val = raw == "1"
                elif t == "str":
                    val = raw
                elif t == "e":
                    val = "#" + raw
                else:
                    try:
                        val = float(raw)
                        if val.is_integer():
                            val = int(val)
                    except ValueError:
                        val = raw
            if ref:
                cells[col_to_idx(ref)] = val
        if cells:
            rows.append(cells)
    return rows

z = zipfile.ZipFile("budget.xlsx")
