        out.append((sh.get("name"), target))
    return out

def read_sheet(z, path, shared):
    root = ET.fromstring(z.read(path))
    rows = []
    for row in root.iter(f"{{{M_NS}}}row"):
        cells = {}
        for c in row.findall(f"{{{M_NS}}}c"):
            ref = c.get("r")
            t = c.get("t")
            v = c.find(f"{{{M_NS}}}v")
            val = None
            if t == "inlineStr":
                is_el = c.find(f"{{{M_NS}}}is")
                if is_el is not None:
                    val = "".join(x.text or "" for x in is_el.iter(f"{{{M_NS}}}t"))
            elif v is not None:
                raw = v.text or ""
                if t == "s":
                    val = shared[int(raw)]
                elif t == "b":
                    val = raw == "1"
                elif t == "str":
                    val = raw
                elif t == "e":
                    val = "#" + raw
                else:
                    try:
                        val = float(raw)
                        if val.is_integer():
                            val = int(val)
                    except ValueError:
                        val = raw
            if ref:
                cells[col_to_idx(ref)] = val
        if cells:
            rows.append(cells)
    return rows

z = zipfile.ZipFile("budget.xlsx")
shared = read_shared_strings(z)
name, path = sheet_map(z)[0]
rows = read_sheet(z, path, shared)

def cell(r, col):
    return r.get(col)

# Find section boundaries
exp_start = next(i for i, r in enumerate(rows) if cell(r, 1) == "EXPENSES")
exp_end = next(i for i, r in enumerate(rows) if i > exp_start and cell(r, 1) == "Total Expenses")

by_category = {}
total = 0.0
for r in rows[exp_start + 1:exp_end]:
    cat = cell(r, 1)
    amt = cell(r, 3)
    if cat is not None and isinstance(amt, (int, float)):
        by_category[cat] = by_category.get(cat, 0.0) + amt
        total += amt

print("Expenses by category:")
for cat in by_category:
    print(f"  {cat}: ${by_category[cat]:,.2f}")
print(f"TOTAL EXPENSES: ${total:,.2f}")
